export const CladeState = Object.freeze({
  ANSWER: 0,
  OFF: 1,
  HIDDEN: 2,
  VISIBLE: 3,
});

export class Clade {
  constructor(tid, ptid, sci_name, com_name, text, image, rank) {
    this.tid = tid;
    this.ptid = ptid;
    this.sci_name = sci_name;
    this.com_name = com_name;
    this.text = text;
    this.image = image;
    this.rank = rank;
    this.sub_ptid = ptid;
    this.onChain = false;
    this.state = CladeState.OFF;
  }

  clone() {
    let clone = new Clade(
      this.tid,
      this.ptid,
      this.sci_name,
      this.com_name,
      this.text,
      this.image,
      this.rank,
    );
    clone.sub_ptid = this.sub_ptid;
    clone.onChain = this.onChain;
    clone.state = this.state;
    return clone;
  }
}

